// Sign the request for the overdue-loan list (n8n -> Convex secret).
const crypto = require('crypto');
const SECRET = $env.HMAC_SECRET_N8N_TO_CONVEX;
if (!SECRET) throw new Error('HMAC_SECRET_N8N_TO_CONVEX is not set on the n8n container');

const body = JSON.stringify({ requestedAt: new Date().toISOString() });
const timestamp = String(Math.floor(Date.now() / 1000));
const signature =
  'sha256=' + crypto.createHmac('sha256', SECRET).update(`${timestamp}.${body}`).digest('hex');

return [{ json: { body, timestamp, signature } }];

// Convex signs the overdue list with the Convex -> n8n secret. Verify it
// before emailing anyone, then emit one item per overdue loan.
const crypto = require('crypto');
const SECRET = $env.HMAC_SECRET_CONVEX_TO_N8N;
const MAX_SKEW_SECONDS = 300;
if (!SECRET) throw new Error('HMAC_SECRET_CONVEX_TO_N8N is not set on the n8n container');

const res = $input.first().json;
const headers = res.headers || {};
// With responseFormat "text" the HTTP node puts the exact body in `data`.
const raw = res.data;
if (typeof raw !== 'string') throw new Error('Expected the raw response body as text');
const timestamp = headers['x-lendloop-timestamp'];
const signature = String(headers['x-lendloop-signature'] || '');

if (!timestamp || Math.abs(Math.floor(Date.now() / 1000) - Number(timestamp)) > MAX_SKEW_SECONDS) {
  throw new Error('Overdue list response has a missing or stale timestamp');
}
const expected =
  'sha256=' + crypto.createHmac('sha256', SECRET).update(`${timestamp}.${raw}`).digest('hex');
const a = Buffer.from(expected);
const b = Buffer.from(signature);
if (a.length !== b.length || !crypto.timingSafeEqual(a, b)) {
  throw new Error('Overdue list response failed signature verification');
}

const { loans } = JSON.parse(raw);
return loans.map((loan) => ({ json: loan }));

// One reminder email per overdue loan. Runs once per item.
const loan = $input.item.json;
const appUrl = $env.LENDLOOP_APP_URL || 'http://localhost:3000';
const from = { Email: $env.LENDLOOP_MAIL_FROM || 'notifications@lendloop.local', Name: 'LendLoop' };
const days = loan.daysOverdue === 1 ? '1 day' : `${loan.daysOverdue} days`;

return {
  json: {
    ...loan,
    mail: {
      From: from,
      To: [{ Email: loan.borrower.email, Name: loan.borrower.firstName }],
      Subject: `Reminder: the ${loan.toolName} is ${days} overdue`,
      Text:
        `Hi ${loan.borrower.firstName},\n\n` +
        `The ${loan.toolName} you borrowed from ${loan.lender.firstName} was due back on ${loan.endDate} ` +
        `(${days} ago). Please return it or get in touch with them.\n\n${appUrl}/requests\n\nLendLoop`,
      Tags: ['lendloop', 'overdue-reminder'],
    },
  },
};

// Record the reminder outcome in Convex. The reminderKey (loan + date) makes
// the write-back idempotent, so n8n retries and re-runs never duplicate.
// Runs once per item; a failed email arrives here with an `error` field
// because the email node continues on error.
const crypto = require('crypto');
const SECRET = $env.HMAC_SECRET_N8N_TO_CONVEX;
if (!SECRET) throw new Error('HMAC_SECRET_N8N_TO_CONVEX is not set on the n8n container');

const loan = $('Compose reminder').item.json;
const failed = Boolean($input.item.json.error);
const payload = {
  loanId: loan.loanId,
  reminderKey: loan.reminderKey,
  outcome: failed ? 'failed' : 'sent',
};
if (failed) payload.detail = 'email provider error';

const body = JSON.stringify(payload);
const timestamp = String(Math.floor(Date.now() / 1000));
const signature =
  'sha256=' + crypto.createHmac('sha256', SECRET).update(`${timestamp}.${body}`).digest('hex');

return { json: { body, timestamp, signature, outcome: payload.outcome } };
